using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Windows;
using TeklaBackupManager;
static class SafetyTests {
static readonly string Root=Path.Combine(Path.GetTempPath(),"Tekla-safety-"+Guid.NewGuid().ToString("N"));
static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Static|BindingFlags.Instance;
static object? Invoke(Type t,string name,object? instance,params object?[] args){try{return t.GetMethod(name,Flags)!.Invoke(instance,args);}catch(TargetInvocationException e){throw e.InnerException!;}}
static object? Call(string name,object? instance,params object?[] args)=>Invoke(typeof(MainWindow),name,instance,args);
static IDisposable Lease(string folder)=> (IDisposable)Invoke(typeof(MainWindow).Assembly.GetType("TeklaBackupManager.ExclusiveLease",true)!,"Acquire",null,folder,".test-profile.lock")!;
static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
static void Reject(Action action){try{action();}catch(InvalidOperationException){return;}throw new Exception("Expected safe rejection");}
static BackupRequest Request(string name,string source="source"){var src=Path.Combine(Root,name,source);Directory.CreateDirectory(src);File.WriteAllText(Path.Combine(src,"model.db1"),source);var dest=Path.Combine(Root,name,"backup");return new(new(),"TEST-USER","WORKSTATION-01",src,dest,Path.Combine(dest,"TEKLASTRUCTUREMODEL","TEST-USER"),"fictitious",false,BackupMode.FullMirror,false,30);}
static void Backup(BackupRequest r,IProgress<BackupProgressInfo>? progress=null,CancellationToken? token=null)=>Call("RunBackup",null,r,progress??new Progress<BackupProgressInfo>(),token??CancellationToken.None);
sealed class Hold(string ready,string release):IProgress<BackupProgressInfo>{public void Report(BackupProgressInfo info){File.WriteAllText(ready,"ready");if(!SpinWait.SpinUntil(()=>File.Exists(release),TimeSpan.FromSeconds(30)))throw new IOException("Test release timeout");}}
static Process Start(string mode,string folder){var psi=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};foreach(var arg in new[]{"--safety-worker",mode,folder})psi.ArgumentList.Add(arg);return Process.Start(psi)!;}
static void WaitReady(Process process,string path){Check(SpinWait.SpinUntil(()=>File.Exists(path)||process.HasExited,TimeSpan.FromSeconds(15))&&File.Exists(path),"Worker did not acquire lease");}
public static int Worker(string[] args){try{var mode=args[1];var folder=args[2];if(mode=="profile"){using var lease=Lease(folder);File.WriteAllText(Path.Combine(folder,"ready"),"ready");if(!SpinWait.SpinUntil(()=>File.Exists(Path.Combine(folder,"release")),TimeSpan.FromSeconds(30)))return 12;return 0;}
var src=Path.Combine(folder,mode=="hold"?"first":"second");Directory.CreateDirectory(src);File.WriteAllText(Path.Combine(src,"model.db1"),mode);var dest=Path.Combine(folder,"backup");var req=new BackupRequest(new(),"TEST-USER","WORKSTATION-01",src,dest,Path.Combine(dest,"TEKLASTRUCTUREMODEL","TEST-USER"),"test",false,BackupMode.FullMirror,false,30);Backup(req,mode=="hold"?new Hold(Path.Combine(folder,"ready"),Path.Combine(folder,"release")):null);return 0;
}catch(InvalidOperationException){return 23;}catch(Exception ex){Console.WriteLine("Worker error: "+ex.GetType().Name);return 24;}}
public static (int Passed,int Failed) Run(){Directory.CreateDirectory(Root);int passed=0,failed=0;
void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.GetType().Name+" "+e.Message);}}
Test("Profile lease rejects another real process and preserves settings",()=>{var folder=Path.Combine(Root,"profile");Directory.CreateDirectory(folder);var settings=Path.Combine(folder,"settings.json");File.WriteAllText(settings,"fictitious settings");using var first=Start("profile",folder);try{WaitReady(first,Path.Combine(folder,"ready"));using var second=Start("profile",folder);Check(second.WaitForExit(10000)&&second.ExitCode==23,"Second profile process not refused");Check(File.ReadAllText(settings)=="fictitious settings","Settings changed");}finally{File.WriteAllText(Path.Combine(folder,"release"),"release");if(!first.WaitForExit(5000))first.Kill(true);}});
Test("Profile lease is released after forced process termination",()=>{var folder=Path.Combine(Root,"killed-profile");Directory.CreateDirectory(folder);using var first=Start("profile",folder);try{WaitReady(first,Path.Combine(folder,"ready"));}finally{if(!first.HasExited){first.Kill(true);first.WaitForExit();}}using var reacquired=Lease(folder);});
Test("Concurrent real destination writer is refused without modifying backup",()=>{var folder=Path.Combine(Root,"concurrent");Directory.CreateDirectory(folder);using var first=Start("hold",folder);try{WaitReady(first,Path.Combine(folder,"ready"));var target=Path.Combine(folder,"backup","TEKLASTRUCTUREMODEL","TEST-USER","model.db1");var before=File.ReadAllBytes(target);using var second=Start("second",folder);Check(second.WaitForExit(10000)&&second.ExitCode==23,"Second writer not refused");Check(before.SequenceEqual(File.ReadAllBytes(target)),"Existing backup changed");}finally{File.WriteAllText(Path.Combine(folder,"release"),"release");if(!first.WaitForExit(5000))first.Kill(true);}});
Test("Destination lease is released after forced termination",()=>{var folder=Path.Combine(Root,"killed-destination");Directory.CreateDirectory(folder);using var first=Start("hold",folder);try{WaitReady(first,Path.Combine(folder,"ready"));}finally{if(!first.HasExited){first.Kill(true);first.WaitForExit();}}var src=Path.Combine(folder,"first");var dest=Path.Combine(folder,"backup");var r=new BackupRequest(new(),"TEST-USER","WORKSTATION-01",src,dest,Path.Combine(dest,"TEKLASTRUCTUREMODEL","TEST-USER"),"test",false,BackupMode.FullMirror,false,30);Backup(r);});
Test("Disposed lease fails closed",()=>{var lease=Lease(Path.Combine(Root,"disposed"));lease.Dispose();Reject(()=>Invoke(lease.GetType(),"EnsureHeld",lease));});
Test("Different source cannot take an already owned destination",()=>{var first=Request("ownership","first");Backup(first);var target=Path.Combine(first.TargetPath,"model.db1");var before=File.ReadAllBytes(target);var second=Request("ownership","second");Reject(()=>Backup(second));Check(before.SequenceEqual(File.ReadAllBytes(target)),"Owner data changed");});
Test("Unowned existing backup is not silently adopted",()=>{var r=Request("legacy");Directory.CreateDirectory(r.TargetPath);var target=Path.Combine(r.TargetPath,"keep.db1");File.WriteAllText(target,"keep");Reject(()=>Backup(r));Check(File.ReadAllText(target)=="keep","Legacy data modified");});
Test("Cancellation releases destination for retry",()=>{var r=Request("cancel");try{Backup(r,null,new CancellationToken(true));throw new Exception("Expected cancellation");}catch(OperationCanceledException){}Backup(r);Check(File.Exists(Path.Combine(r.TargetPath,"model.db1")),"Retry failed");});
foreach(var name in new[]{"CON","nul.txt","COM1","LPT9.log","COM¹","user.","user ","User:A"})Test("Refuse unsafe Windows user name "+name,()=>Reject(()=>Call("SanitizeFolderName",null,name)));
foreach(var pair in new[]{new[]{"User-A","user-a"},new[]{"User:A","User?A"}})Test("Configured user collision refused before writing",()=>{var profile=Path.Combine(Root,Guid.NewGuid().ToString("N"));var w=(MainWindow)Activator.CreateInstance(typeof(MainWindow),BindingFlags.Instance|BindingFlags.NonPublic,null,new object?[]{profile,false},null)!;object Get(string name)=>typeof(MainWindow).GetField(name,Flags)!.GetValue(w)!;try{((System.Windows.Controls.TextBox)Get("DestinationPathBox")).Text=Path.Combine(profile,"backup");var employees=(System.Collections.ObjectModel.ObservableCollection<EmployeeBackupConfig>)Get("_employees");employees.Clear();foreach(var user in pair)employees.Add(new(){EmployeeName=user,MachineName="WORKSTATION-01",SourcePath=Path.Combine(profile,"source"),DailyDb1Time="12:15",WeeklyFullTime="12:30",IsEnabled=true});Reject(()=>Call("BuildRequests",w,BackupMode.FullMirror,new[]{employees[0]}));Check(!Directory.Exists(Path.Combine(profile,"backup")),"Destination changed before collision rejection");}finally{typeof(MainWindow).GetField("_isExitRequested",Flags)!.SetValue(w,true);w.Close();}});

Test("Closed lease handle fails closed",()=>{using var lease=Lease(Path.Combine(Root,"closed-handle"));var stream=(FileStream)lease.GetType().GetField("stream",Flags)!.GetValue(lease)!;stream.Dispose();Reject(()=>Invoke(lease.GetType(),"EnsureHeld",lease));});
foreach(var name in new[]{"CON .txt","LPT².log"})Test("Refuse reserved device alias "+name,()=>Reject(()=>Call("SanitizeFolderName",null,name)));
foreach(var alias in new[]{"source.","source "})Test("Refuse ambiguous Windows path component",()=>{var r=Request("ambiguous-"+Guid.NewGuid().ToString("N"));var parent=Path.GetDirectoryName(r.SourcePath)!;r=r with{SourcePath=Path.Combine(parent,alias)};Reject(()=>Backup(r));Check(!Directory.Exists(r.TargetPath),"Ambiguous operation wrote backup");});
Test("Canceled staged file copy preserves original target bytes",()=>{var dir=Path.Combine(Root,"atomic");Directory.CreateDirectory(dir);var src=Path.Combine(dir,"source.db1");using(var f=File.Create(src)){f.SetLength(32*1024*1024);}var dest=Path.Combine(dir,"existing.db1");File.WriteAllText(dest,"original-content");using var lease=Lease(Path.Combine(Root,"atomic-lease"));using var cts=new CancellationTokenSource();var cancel=Task.Run(()=>{if(SpinWait.SpinUntil(()=>Directory.EnumerateFiles(dir,".tekla-copy-*.partial").Any(),TimeSpan.FromSeconds(15)))cts.Cancel();});try{Call("CopyFileSafely",null,src,dest,lease,cts.Token);throw new Exception("Expected cancellation during staging");}catch(OperationCanceledException){}cancel.Wait();Check(File.ReadAllText(dest)=="original-content","Existing target was truncated");});

Test("Same-length immediate model change is not skipped",()=>{var r=Request("same-length");Backup(r);File.WriteAllText(Path.Combine(r.SourcePath,"model.db1"),"change");File.SetLastWriteTimeUtc(Path.Combine(r.SourcePath,"model.db1"),File.GetLastWriteTimeUtc(Path.Combine(r.TargetPath,"model.db1")));Backup(r);Check(File.ReadAllText(Path.Combine(r.TargetPath,"model.db1"))=="change","Same-size content change missed");});
Test("Source manifest is preserved byte for byte",()=>{var r=Request("source-manifest");File.WriteAllText(Path.Combine(r.SourcePath,"manifest.txt"),"legitimate model file");Backup(r);Check(File.ReadAllText(Path.Combine(r.TargetPath,"manifest.txt"))=="legitimate model file","Source manifest overwritten");});
Test("Nested destination roots cannot bypass writer protection",()=>{var first=Request("nested-roots");Backup(first);var second=Request("nested-source");second=second with{DestinationRoot=Path.Combine(first.TargetPath,"nested"),TargetPath=Path.Combine(first.TargetPath,"nested","TEKLASTRUCTUREMODEL","TEST-USER")};Reject(()=>Backup(second));Check(!Directory.Exists(second.TargetPath),"Nested destination modified");});
Test("Outer destination cannot enclose a managed backup root",()=>{var inner=Request("outer-roots");Backup(inner);var outer=Request("outer-source");outer=outer with{DestinationRoot=Path.GetDirectoryName(inner.DestinationRoot)!,TargetPath=Path.Combine(Path.GetDirectoryName(inner.DestinationRoot)!,"TEKLASTRUCTUREMODEL","TEST-USER")};Reject(()=>Backup(outer));Check(!Directory.Exists(outer.TargetPath),"Outer destination modified");});
Test("Empty DB1 does not purge existing valid history",()=>{var r=Request("empty-db1");r=r with{Mode=BackupMode.Db1Timestamped,TargetPath=Path.Combine(r.DestinationRoot,"BACKUPDB1","TEST-USER",DateTime.Now.ToString("yyyy-dd-MM")),EnableRetention=true};Backup(r);var old=Path.Combine(Path.GetDirectoryName(r.TargetPath)!,DateTime.Now.AddDays(-100).ToString("yyyy-dd-MM"));Directory.CreateDirectory(old);var original=Path.Combine(old,"keep.db1");File.WriteAllText(original,"valid history");Directory.SetCreationTime(old,DateTime.Now.AddDays(-100));Directory.SetLastWriteTime(old,DateTime.Now.AddDays(-100));File.Delete(Path.Combine(r.SourcePath,"model.db1"));Reject(()=>Backup(r));Check(File.ReadAllText(original)=="valid history","History purged without replacement");});
Test("Volume root contains a child path without scanning the volume",()=>{var volume=Path.GetPathRoot(Root)!;Check((bool)Call("IsSameOrDescendant",null,Path.Combine(volume,"FictitiousBackups"),volume)!,"Root overlap missed");});
Test("Normalized parent aliases are recognized",()=>{var parent=Path.Combine(Root,"parent");Check((bool)Call("IsSameOrDescendant",null,Path.Combine(parent,"child","..","backup"),parent)!,"Normalized overlap missed");});
foreach(var path in new[]{"//?/C:/fictitious","//./C:/fictitious"})Test("Reject alternate device path spelling",()=>Reject(()=>Call("NormalizeBackupPath",null,path)));
return(passed,failed);}
}
